const withUser = (init, u) => (u ? { ...init, name: u.name || init.name, email: u.email || init.email } : init)

const INIT = {
  name: 'Sarah Mitchell',
  title: 'Head of payments',
  email: 'sarah.mitchell@relay.so',
  location: 'London, United Kingdom',
  timezone: '(GMT+00:00) London',
}
const TZ = [
  '(GMT−08:00) Los Angeles',
  '(GMT−06:00) Mexico City',
  '(GMT−05:00) New York',
  '(GMT−05:00) Toronto',
  '(GMT−03:00) São Paulo',
  '(GMT+00:00) London',
  '(GMT+00:00) Dublin',
  '(GMT+01:00) Amsterdam',
  '(GMT+01:00) Berlin',
  '(GMT+01:00) Paris',
  '(GMT+01:00) Zurich',
  '(GMT+02:00) Tallinn',
  '(GMT+03:00) Riyadh',
  '(GMT+04:00) Dubai',
  '(GMT+05:30) Mumbai',
  '(GMT+08:00) Singapore',
  '(GMT+08:00) Hong Kong',
  '(GMT+09:00) Tokyo',
  '(GMT+09:00) Seoul',
  '(GMT+10:00) Sydney',
  '(GMT+12:00) Auckland',
]
const LABELS = [
  ['name', 'Full name'],
  ['title', 'Role'],
  ['email', 'Email'],
  ['location', 'Location'],
  ['timezone', 'Time zone'],
]
const ACT = [
  ['fx', 'Compared Meridian FX, Cobalt Markets and Pacifica FX', '2h ago'],
  ['kyc', 'Requested an intro from Kestrel Identity', 'Today'],
  ['payouts', 'Added Ledgerline to EU payout partners', 'Mon'],
  ['cards', 'Moved Northbeam Cards to integrating', 'Oct 9'],
  ['all', 'Updated workspace weighting', 'Oct 6'],
]
class Component extends DCLogic {
  state = { saved: withUser(INIT, this.props.user), draft: withUser(INIT, this.props.user), flash: false, ask: false }
  renderVals() {
    const S = this.state,
      dirty = LABELS.some(([k]) => S.draft[k] !== S.saved[k])
    return {
      saved: S.saved,
      fields: LABELS.map(([k, label]) => ({
        label,
        value: S.draft[k],
        isSelect: k === 'timezone',
        isText: k !== 'timezone',
        options: TZ,
        onChange: (e) => {
          const v = e.target.value
          this.setState((s) => ({ draft: { ...s.draft, [k]: v } }))
        },
      })),
      dirtyOp: dirty ? 1 : 0,
      dirtyPe: dirty ? 'auto' : 'none',
      saveFg: dirty ? '#0f1011' : '#62666d',
      saveBg: dirty ? '#f7f8f8' : 'rgba(255,255,255,.05)',
      savedOp: S.flash ? 1 : 0,
      save: () => {
        if (!dirty) return
        this.setState((s) => ({ saved: s.draft, flash: true }))
        this.props.onToast?.('Profile updated', 'success', 'Your details are saved.')
        clearTimeout(this.t)
        this.t = setTimeout(() => this.setState({ flash: false }), 1600)
      },
      discard: () => this.setState({ ask: true }),
      ask: S.ask,
      askYes: () => this.setState((s) => ({ ask: false, draft: s.saved })),
      askNo: () => this.setState({ ask: false }),
      activity: ACT.map(([kind, text, when]) => ({ kind, text, when })),
    }
  }
}

{
  const designVals = Component.prototype.renderVals
  const appVals = function () {
    return { avatar: userAvatar(this.props.user, 'https://randomuser.me/api/portraits/women/44.jpg') }
  }
  Component.prototype.renderVals = function () {
    const v = designVals.call(this)
    return { ...v, ...appVals.call(this, v) }
  }
}

